import{_ as o,l as i,o as a,c as s,v as d,p as n,x as t,d as l,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"d 叉堆与索引堆","description":"","frontmatter":{"title":"d 叉堆与索引堆","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dary-heap.md","filePath":"cs/dary-heap.md","lastUpdated":1789023840000}'),h={name:"cs/dary-heap.md"};function _(m,e,u,A,T,f){const r=i("Mermaid");return a(),s("div",null,[e[1]||(e[1]=d('<h1 id="d-叉堆与索引堆" tabindex="-1">d 叉堆与索引堆 <a class="header-anchor" href="#d-叉堆与索引堆" aria-label="Permalink to &quot;d 叉堆与索引堆&quot;">​</a></h1><div class="epigraph"><p>每个节点 $d$ 个孩子，树更矮，下滤比较次数变多；再存从元素到下标的句柄，decrease-key 才不必先扫全表。</p><footer>—— 据 Johnson, Priority Queues with Update and Finding Minimum Spanning Trees, 1975；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/heap-priority">上一课</a>钉了二叉堆：完全树、数组下标 \\(2i,2i+1\\)、insert/extract-min 为 \\(\\Theta(\\log n)\\)，并声明 decrease-key 需要句柄、\\(d\\) 叉不在那一课。本课不重讲堆序。缺口是两个实现参数：扇出 \\(d\\) 改变高度与下滤代价；索引（句柄）让「已知元素降键」真正 \\(\\Theta(d\\log_d n)\\)。散列课马上要另一条 \\(O(1)\\) 期望查找，对象不同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>二叉下滤每层比两个孩子。\\(d\\) 叉：孩子是 \\(di+1,\\ldots,di+d\\)，高度 \\(\\Theta(\\log_d n)=\\Theta(\\log n/\\log d)\\)，insert 上滤更快，extract-min 每层要在 \\(d\\) 个孩子里找最小。Johnson 用它调最短路里堆的常数。缺口不是斐波那契堆，而是<strong>同一套堆序下改扇出</strong>。</p><p>无句柄的 decrease-key 要先找到元素，\\(\\Theta(n)\\)，堆的对数没有意义。索引堆：<code>pos[id]</code> 存堆数组下标，交换时两边更新。</p><p><span class="marginnote">\\(d=4\\) 在 cache 行上有时更好：一层孩子更连续。过大则下滤的线性扫吃掉高度收益。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数组表示不变，只改父子公式。上滤与父比；下滤在 \\(d\\) 个孩子中取最小再比。索引：对外 id 稳定，对内下标变；<code>swap</code> 必须维护 <code>pos</code>。</p>',9)),(a(),n(c,null,{default:t(()=>[p(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ID%5B%22%E5%85%83%E7%B4%A0%20id%22%5D%20--%3E%20POS%5B%22pos%5Bid%5D%20%E4%B8%8B%E6%A0%87%22%5D%0A%20%20POS%20--%3E%20ARR%5B%22%E5%A0%86%E6%95%B0%E7%BB%84%22%5D%0A%20%20ARR%20--%3E%20CH%5B%22d%20%E4%B8%AA%E5%AD%A9%E5%AD%90%E8%BF%9E%E7%BB%AD%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=d('<p>建堆仍可自底向上 \\(\\Theta(n)\\)：每层工作与 \\(d\\) 有关，渐近仍线性。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Dijkstra 一类反复 decrease-key 的算法，合同必须提供句柄。二叉够用时不必上 \\(d\\)；只有剖析显示 extract 与 insert 比例极端，才调 \\(d\\)。这是常数与 cache 的事，不是新 ADT。</p><p>与 B+ 对照：堆不支持高效任意键查找与中序。索引只映射「已知 id」，不是字典。字典是下一课散列或回到树。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入二项堆、斐波那契摊还，不把操作系统就绪队列绑死为 \\(d\\) 叉。也不把 <code>pos</code> 数组写成必须全局 \\(n\\) 大——可用卫星指针反指堆槽。</p><p>后课默认：优先队列可以是二叉或 \\(d\\) 叉，decrease-key 靠句柄。无序键的期望常数查找靠散列函数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(d\\) 叉降低高度、加重每层比较；数组公式改孩子跨度。</li><li>索引堆维护 id→下标，decrease-key 才对数。</li><li>任意键期望 \\(O(1)\\) 是下一课 \\(h(k)\\)，不是堆。</li><li>出处：Williams, <em>CACM</em>, 1964（二叉）；Johnson, 1975；Cormen et al. 第 6 章。</li></ul>',9))])}const k=o(h,[["render",_]]);export{E as __pageData,k as default};
